CREATE OR REPLACE TRIGGER TM_ACTIVE_WORKSPACE_FROZEN BEFORE INSERT OR UPDATE OR DELETE ON TM_ACTIVE_WORKSPACE
DECLARE active_rows NUMBER;
BEGIN
    SELECT COUNT(*) INTO active_rows FROM TMR_WORKSPACE WHERE ID=1;
    IF active_rows>0 THEN
        RAISE_APPLICATION_ERROR(-20001,'Workspace migrated to relational Oracle tables; legacy JSON is archived.');
    END IF;
END;
/
